#include <iostream>
#include <limits>
#include <optional>
#include <vector>

std::optional<int> smallestOrNone(const std::vector<int>& nums) {
    if (nums.empty()) {
        return std::nullopt;
    }
    int best = std::numeric_limits<int>::max();
    for (int x : nums) {
        if (x < best) {
            best = x;
        }
    }
    return best;
}

int main() {
    int n;
    std::cin >> n;
    std::vector<int> nums(n);
    for (int i = 0; i < n; i++) {
        std::cin >> nums[i];
    }
    std::optional<int> result = smallestOrNone(nums);
    if (result) {
        std::cout << *result << "\n";
    } else {
        std::cout << "none\n";
    }
    return 0;
}

