package main

import (
	"fmt"
	"math"
)

func smallestOrNone(nums []int) *int {
	if len(nums) == 0 {
		return nil
	}
	best := math.MaxInt64
	for _, x := range nums {
		if x < best {
			best = x
		}
	}
	return &best
}

func main() {
	var n int
	fmt.Scan(&n)
	nums := make([]int, n)
	for i := range nums {
		fmt.Scan(&nums[i])
	}
	result := smallestOrNone(nums)
	if result == nil {
		fmt.Println("none")
	} else {
		fmt.Println(*result)
	}
}
